Access parse_access(std::string_view s){if(s=="rw")return Access::read_write;if(s=="r")return Access::read;if(s=="none")return Access::none;throw Error(ExitCode::lua_failure,"invalid Lua workspace access: "+std::string(s));}GuardrailProfile parse_profile(std::string_view s){if(s=="review")return GuardrailProfile::review;if(s=="balanced")return GuardrailProfile::balanced;if(s=="autonomous")return GuardrailProfile::autonomous_mode;throw Error(ExitCode::lua_failure,"invalid Lua guardrail profile: "+std::string(s));}SandboxMode parse_sandbox(std::string_view s){if(s=="strict")return SandboxMode::strict;if(s=="best-effort")return SandboxMode::best_effort;if(s=="off")return SandboxMode::off;throw Error(ExitCode::lua_failure,"invalid Lua command sandbox: "+std::string(s));}
std::filesystem::path canonical_dir(const std::filesystem::path&p,const char*what){std::error_code ec;auto c=std::filesystem::canonical(p,ec);if(ec||!std::filesystem::is_directory(c))throw Error(ExitCode::invalid_input,std::string(what)+" is not an existing directory: "+p.string());return c;}std::filesystem::path resolve_agent_root(const CliOptions&o){if(o.agent_root)return canonical_dir(*o.agent_root,"agent root");std::vector<std::filesystem::path>candidates{std::filesystem::current_path()};if(!o.program_path.empty()){std::error_code ec;auto p=std::filesystem::weakly_canonical(o.program_path,ec);if(!ec){p=p.parent_path();for(int i=0;i<4&&!p.empty();++i){candidates.push_back(p);p=p.parent_path();}}}for(auto&p:candidates)if(std::filesystem::exists(p/"config/agent.lua"))return canonical_dir(p,"agent root");throw Error(ExitCode::invalid_input,"cannot locate agent root; use ./run.sh or --agent-root PATH");}std::filesystem::path resolve_relative(const std::filesystem::path&base,const std::filesystem::path&p){return p.is_absolute()?p:base/p;}
void append_audit(const std::optional<std::filesystem::path>&path,const JsonValue&v){if(!path)return;std::error_code ec;if(!path->parent_path().empty())std::filesystem::create_directories(path->parent_path(),ec);std::ofstream f(*path,std::ios::app);if(f){f<<serialize_json(v)<<'\n';f.close();::chmod(path->c_str(),0600);}}
volatile sig_atomic_t signal_write_fd=-1;void on_sigint(int){int fd=(int)signal_write_fd;if(fd>=0){char c=1;(void)::write(fd,&c,1);}}
class TaskSignal{public:TaskSignal(){if(pipe(fds_)!=0)throw Error(ExitCode::internal_failure,"cannot create signal pipe");signal_write_fd=fds_[1];struct sigaction sa{};sa.sa_handler=on_sigint;sigemptyset(&sa.sa_mask);sigaction(SIGINT,&sa,&old_);watcher_=std::jthread([this](std::stop_token){char c;if(::read(fds_[0],&c,1)>0&&c!=0)source_.request_stop();});}~TaskSignal(){sigaction(SIGINT,&old_,nullptr);signal_write_fd=-1;char c=0;(void)::write(fds_[1],&c,1);if(watcher_.joinable())watcher_.join();::close(fds_[1]);::close(fds_[0]);}std::stop_token token()const{return source_.get_token();}private:int fds_[2]{-1,-1};struct sigaction old_{};std::stop_source source_;std::jthread watcher_;};
std::string slash_help(){return "/help  /status  /scope  /policy  /tools  /changes  /thinking [on|off]  /clear  /exit";}
